        uint32_t bit;

        FLAC__ASSERT(0 != br);
        FLAC__ASSERT(0 != br->buffer);

        *val = 0;
        while(1) {
                if(!FLAC__bitreader_read_bit(br, &bit))
                        return false;
                if(bit)
                        break;
                else
                        *val++;
        }
        return true;
}
